48	    @Override
49	    public String execute(CommandContext commandContext, String[] args) {
50	        logger.info("receive offline command");
51	        String servicePattern = ".*";
52	        if (ArrayUtils.isNotEmpty(args)) {
53	            servicePattern = args[0];
54	        }
55	
56	        boolean hasService = doExecute(servicePattern);
57	
58	        if (hasService) {
59	            return "OK";
60	        } else {
61	            return "service not found";
62	        }
63	    }
