69	    public boolean offline(String servicePattern) {
70	        boolean hasService = false;
71	
72	        ExecutorService executorService = Executors.newFixedThreadPool(
73	                Math.min(Runtime.getRuntime().availableProcessors(), 4), new NamedThreadFactory("Dubbo-Offline"));
74	        try {
75	            List<CompletableFuture<Void>> futures = new LinkedList<>();
76	            Collection<ProviderModel> providerModelList = serviceRepository.allProviderModels();
77	            for (ProviderModel providerModel : providerModelList) {
78	                ServiceMetadata metadata = providerModel.getServiceMetadata();
79	                if (metadata.getServiceKey().matches(servicePattern)
80	                        || metadata.getDisplayServiceKey().matches(servicePattern)) {
81	                    hasService = true;
82	                    List<ProviderModel.RegisterStatedURL> statedUrls = providerModel.getStatedUrl();
83	                    for (ProviderModel.RegisterStatedURL statedURL : statedUrls) {
84	                        if (statedURL.isRegistered()) {
85	                            futures.add(CompletableFuture.runAsync(
86	                                    () -> {
87	                                        doUnexport(statedURL);
88	                                    },
89	                                    executorService));
90	                        }
91	                    }
92	                }
93	            }
94	            for (CompletableFuture<Void> future : futures) {
95	                future.get();
96	            }
97	        } catch (ExecutionException | InterruptedException e) {
98	            throw new RuntimeException(e);
99	        } finally {
100	            executorService.shutdown();
101	        }
102	
103	        return hasService;
