34	public class BaseOnline implements BaseCommand {
35	    private static final Logger logger = LoggerFactory.getLogger(BaseOnline.class);
36	    public FrameworkServiceRepository serviceRepository;
37	
38	    public BaseOnline(FrameworkModel frameworkModel) {
39	        this.serviceRepository = frameworkModel.getServiceRepository();
40	    }
41	
42	    @Override
43	    public String execute(CommandContext commandContext, String[] args) {
44	        logger.info("receive online command");
45	        String servicePattern = ".*";
46	        if (ArrayUtils.isNotEmpty(args)) {
47	            servicePattern = "" + args[0];
48	        }
49	
50	        boolean hasService = doExecute(servicePattern);
51	        if (hasService) {
52	            return "OK";
53	        } else {
54	            return "service not found";
55	        }
56	    }
57	
58	    public boolean online(String servicePattern) {
59	        boolean hasService = false;
60	
61	        Collection<ProviderModel> providerModelList = serviceRepository.allProviderModels();
62	        for (ProviderModel providerModel : providerModelList) {
63	            ServiceMetadata metadata = providerModel.getServiceMetadata();
64	            if (metadata.getServiceKey().matches(servicePattern)
65	                    || metadata.getDisplayServiceKey().matches(servicePattern)) {
66	                hasService = true;
67	                List<ProviderModel.RegisterStatedURL> statedUrls = providerModel.getStatedUrl();
68	                for (ProviderModel.RegisterStatedURL statedURL : statedUrls) {
69	                    if (!statedURL.isRegistered()) {
70	                        doExport(statedURL);
71	                    }
72	                }
73	            }
74	        }
75	
76	        return hasService;
77	    }
78	
79	    protected boolean doExecute(String servicePattern) {
80	        return this.online(servicePattern);
81	    }
82	
83	    protected void doExport(ProviderModel.RegisterStatedURL statedURL) {
84	        RegistryFactory registryFactory = statedURL
85	                .getRegistryUrl()
86	                .getOrDefaultApplicationModel()
87	                .getExtensionLoader(RegistryFactory.class)
88	                .getAdaptiveExtension();
89	        Registry registry = registryFactory.getRegistry(statedURL.getRegistryUrl());
90	        registry.register(statedURL.getProviderUrl());
91	        statedURL.setRegistered(true);
92	    }
